INSERT INTO public.drug_labels (id, set_id, effective_time, brand_name, generic_name, substance_name, manufacturer_name, route, product_type, pharmacologic_class, rxcui, label_json, created_at) VALUES ('ee8e3aa2-8550-41c7-9911-0723b3fb2f87', '0005aafa-08f8-4990-a54d-cc097195708f', '20260102', 'Pain Reliever Extra Strength', 'ACETAMINOPHEN', 'ACETAMINOPHEN', 'Valu Merchandisers Company', 'ORAL', 'HUMAN OTC DRUG', '{}', '{"198440"}', '{"id":"ee8e3aa2-8550-41c7-9911-0723b3fb2f87","set_id":"0005aafa-08f8-4990-a54d-cc097195708f","openfda":{"route":["ORAL"],"rxcui":["198440"],"brand_name":["Pain Reliever Extra Strength"],"generic_name":["ACETAMINOPHEN"],"product_type":["HUMAN OTC DRUG"],"substance_name":["ACETAMINOPHEN"],"manufacturer_name":["Valu Merchandisers Company"]},"purpose":["Purpose Pain reliever/fever reducer"],"warnings":["Warnings Liver warning: This product contains acetaminophen. Severe liver damage may occur if you take more than 4,000 mg of acetaminophen in 24 hours with other drugs containing acetaminophen 3 or more alcoholic drinks every day while using this product Allergy alert: Acetaminophen may cause severe skin reactions. Symptoms may include: skin reddening blisters rash If a skin reaction occurs, stop use and seek medical help right away. Do not use if you are allergic to acetaminophen or any of the inactive ingredients in this product with any other drug containing acetaminophen (prescription or nonprescription). If you are not sure whether a drug contains acetaminophen, ask a doctor or pharmacist. Ask a doctor before use if you have liver disease. Ask a doctor or pharmacist before use if you are taking the blood thinning drug warfarin. Stop use and ask a doctor if new symptoms occur pain gets worse or lasts more than 10 days fever gets worse or lasts more than 3 days redness or swelling is present These could be signs of a serious condition. If pregnant or breast-feeding, ask a health professional before use. Keep out of reach of children. In case of overdose, get medical help or contact a Poison Control Center right away. Prompt medical attention is critical for adults as well as for children even if you do not notice any signs or symptoms."],"effective_time":"20260102","indications_and_usage":["Uses temporarily relieves minor aches and pains due to: headache the common cold backache minor pain of arthritis toothache muscular aches premenstrual and menstrual cramps temporarily reduces fever"],"dosage_and_administration":["Directions do not take more than directed adults and children 12 years and over take 2 gelcaps every 6 hours while symptoms last do not take more than 6 gelcaps in 24 hours, unless directed by a doctor do not take for more than 10 days unless directed by a doctor children under 12 years: ask a doctor"]}'::jsonb, '2026-08-26T12:26:20.41084+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.drug_labels (id, set_id, effective_time, brand_name, generic_name, substance_name, manufacturer_name, route, product_type, pharmacologic_class, rxcui, label_json, created_at) VALUES ('4bd1345d-d116-426e-825f-bbf29381746a', '00653b7c-7099-487e-9a01-e89781c21323', '20260429', 'Ibuprofen Dye Free', 'IBUPROFEN', 'IBUPROFEN', 'CVS Pharmacy', 'ORAL', 'HUMAN OTC DRUG', '{"Nonsteroidal Anti-inflammatory Drug [EPC]"}', '{"310965"}', '{"id":"4bd1345d-d116-426e-825f-bbf29381746a","set_id":"00653b7c-7099-487e-9a01-e89781c21323","openfda":{"route":["ORAL"],"rxcui":["310965"],"brand_name":["Ibuprofen Dye Free"],"generic_name":["IBUPROFEN"],"product_type":["HUMAN OTC DRUG"],"substance_name":["IBUPROFEN"],"pharm_class_epc":["Nonsteroidal Anti-inflammatory Drug [EPC]"],"manufacturer_name":["CVS Pharmacy"]},"purpose":["Purpose Pain reliever/fever reducer"],"warnings":["Warnings Allergy alert: Ibuprofen may cause a severe allergic reaction, especially in people allergic to aspirin. Symptoms may include: rash facial swelling asthma (wheezing) hives skin reddening shock blisters If an allergic reaction occurs, stop use and seek medical help right away. Stomach bleeding warning: This product contains an NSAID, which may cause severe stomach bleeding. The chance is higher if you: take more or for a longer time than directed take a blood thinning (anticoagulant) or steroid drug have had stomach ulcers or bleeding problems have 3 or more alcoholic drinks every day while using this product are age 60 or older take other drugs containing prescription or nonprescription NSAIDs [aspirin, ibuprofen, naproxen, or others] Heart attack and stroke warning: NSAIDs, except aspirin, increase the risk of heart attack, heart failure, and stroke. These can be fatal. The risk is higher if you use more than directed or for longer than directed. Do not use if you have ever had an allergic reaction to any other pain reliever/fever reducer right before or after heart surgery Ask a doctor before use if stomach bleeding warning applies to you you have a history of stomach problems, such as heartburn you have high blood pressure, heart disease, liver cirrhosis, kidney disease, asthma, or had a stroke you are taking a diuretic you have problems or serious side effects from taking pain relievers or fever reducers Ask a doctor or pharmacist before use if you are under a doctor''s care for any serious condition taking aspirin for heart attack or stroke, because ibuprofen may decrease this benefit of aspirin taking any other drug When using this product take with food or milk if stomach upset occurs Stop use and ask a doctor if you experience any of the following signs of stomach bleeding: feel faint have bloody or black stools vomit blood have stomach pain that does not get better you have symptoms of heart problems or stroke: chest pain slurred speech trouble breathing leg swelling weakness in one part or side of body pain gets worse or lasts more than 10 days fever gets worse or lasts more than 3 days redness or swelling is present in the painful area any new symptoms appear If pregnant or breast-feeding, ask a health professional before use. It is especially important not to use ibuprofen at 20 weeks or later in pregnancy unless definitely directed to do so by a doctor because it may cause problems in the unborn child or complications during delivery. Keep out of reach of children. In case of overdose, get medical help or contact a Poison Control Center right away."],"effective_time":"20260429","indications_and_usage":["Uses temporarily relieves minor aches and pains due to: headache toothache backache menstrual cramps the common cold muscular aches minor pain of arthritis temporarily reduces fever"],"dosage_and_administration":["Directions do not take more than directed the smallest effective dose should be used adults and children 12 years and over: take 1 tablet every 4 to 6 hours while symptoms persist if pain or fever does not respond to 1 tablet, 2 tablets may be used do not exceed 6 tablets in 24 hours, unless directed by a doctor children under 12 years: ask a doctor"]}'::jsonb, '2026-08-26T12:28:50.347908+00:00') ON CONFLICT (id) DO NOTHING;
