INSERT INTO public.label_chunks (id, label_id, section_key, section_title, content, embedding, created_at) VALUES ('b9b6a54e-d2df-4412-95f7-6265840cdaab', 'ee8e3aa2-8550-41c7-9911-0723b3fb2f87', 'warnings', 'Warnings', 'Warnings Liver warning: This product contains acetaminophen. Severe liver damage may occur if you take more than 4,000 mg of acetaminophen in 24 hours with other drugs containing acetaminophen 3 or more alcoholic drinks every day while using this product Allergy alert: Acetaminophen may cause severe skin reactions. Symptoms may include: skin reddening blisters rash If a skin reaction occurs, stop use and seek medical help right away. Do not use if you are allergic to acetaminophen or any of the inactive ingredients in this product with any other drug containing acetaminophen (prescription or nonprescription). If you are not sure whether a drug contains acetaminophen, ask a doctor or pharmacist. Ask a doctor before use if you have liver disease. Ask a doctor or pharmacist before use if you are taking the blood thinning drug warfarin. Stop use and ask a doctor if new symptoms occur pain gets worse or lasts more than 10 days fever gets worse or lasts more than 3 days redness or swelling is present These could be signs of a serious condition. If pregnant or breast-feeding, ask a health professional before use. Keep out of reach of children.', '[-0.016113281,0.0146102905,0.0446167,0.055389404,-0.03479004,-0.017456055,0.01966858,0.0061531067,-0.054656982,0.0050811768,-0.029418945,0.008232117,-0.010971069,0.043823242,0.011978149,0.026824951,0.032196045,0.0027484894,-0.06781006,-0.0025672913,0.0076522827,0.034423828,-0.01902771,0.0063476562,0.013946533,-0.005393982,0.010414124,-0.07305908,-0.005622864,-0.02909851,0.020751953,-0.0140686035,0.02468872,0.024719238,0.006866455,-0.041107178,0.044036865,0.020858765,-0.03164673,-0.02128601,-0.031433105,-0.019973755,0.022094727,0.031585693,-0.04244995,-0.018798828,-0.015960693,-0.019424438,0.032348633,-0.006263733,-