INSERT INTO public.label_chunks (id, label_id, section_key, section_title, content, embedding, created_at) VALUES ('48f96224-7683-4584-a823-91135b305924', '4bd1345d-d116-426e-825f-bbf29381746a', 'warnings', 'Warnings', 'Warnings Allergy alert: Ibuprofen may cause a severe allergic reaction, especially in people allergic to aspirin. Symptoms may include: rash facial swelling asthma (wheezing) hives skin reddening shock blisters If an allergic reaction occurs, stop use and seek medical help right away. Stomach bleeding warning: This product contains an NSAID, which may cause severe stomach bleeding. The chance is higher if you: take more or for a longer time than directed take a blood thinning (anticoagulant) or steroid drug have had stomach ulcers or bleeding problems have 3 or more alcoholic drinks every day while using this product are age 60 or older take other drugs containing prescription or nonprescription NSAIDs [aspirin, ibuprofen, naproxen, or others] Heart attack and stroke warning: NSAIDs, except aspirin, increase the risk of heart attack, heart failure, and stroke. These can be fatal. The risk is higher if you use more than directed or for longer than directed.', '[-0.04055786,0.02571106,0.05633545,0.033233643,-0.056121826,-0.037109375,-0.0031909943,0.005519867,-0.031433105,-0.029067993,-0.008049011,-0.0050354004,-0.026275635,0.028839111,0.012298584,0.0069122314,-0.002632141,0.02015686,-0.053619385,0.012207031,-0.0010118484,0.064453125,-0.008766174,0.01348114,0.030319214,-0.0018234253,0.02557373,-0.047698975,0.015930176,-0.006626129,0.018463135,-0.011932373,0.031204224,0.029220581,0.020950317,-0.0345459,0.023635864,0.017181396,0.01663208,-0.020370483,-0.04107666,-0.006626129,0.03994751,0.018188477,-0.06530762,0.007095337,0.015594482,-0.006454468,0.0063819885,0.0047912598,-0.03994751,-0.021636963,-0.042114258,0.05911255,-0.014915466,-0.017440796,0.007423401,0.015548706,-0.002840042,0.03579712,0.004135132,-0.016326904,-0.024383545,-0.013496399,-0.019119263,