INSERT INTO public.label_chunks (id, label_id, section_key, section_title, content, embedding, created_at) VALUES ('8be83c0a-a598-4625-83dd-ba86bf14262d', '4bd1345d-d116-426e-825f-bbf29381746a', 'warnings', 'Warnings', 'Do not use if you have ever had an allergic reaction to any other pain reliever/fever reducer right before or after heart surgery Ask a doctor before use if stomach bleeding warning applies to you you have a history of stomach problems, such as heartburn you have high blood pressure, heart disease, liver cirrhosis, kidney disease, asthma, or had a stroke you are taking a diuretic you have problems or serious side effects from taking pain relievers or fever reducers Ask a doctor or pharmacist before use if you are under a doctor''s care for any serious condition taking aspirin for heart attack or stroke, because ibuprofen may decrease this benefit of aspirin taking any other drug When using this product take with food or milk if stomach upset occurs Stop use and ask a doctor if you experience any of the following signs of stomach bleeding: feel faint have bloody or black stools vomit blood have stomach pain that does not get better you have symptoms of heart problems or stroke: chest pain slurred speech trouble breathing leg swelling weakness in one part or side of body pain gets worse or lasts more than 10 days fever gets worse or lasts more than 3 days redness or swelling is present in the painful area any new symptoms appear If pregnant or breast-feeding, ask a health professional before use.', '[-0.015808105,0.034179688,0.030029297,0.021072388,-0.059448242,-0.026519775,-0.011238098,0.022018433,-0.02658081,-0.019012451,4.053116e-06,-0.0038776398,-0.051605225,0.020019531,0.04458618,0.044128418,-0.0058670044,-0.012382507,-0.057647705,-0.004070282,-0.00058841705,0.03451538,-0.0015983582,0.020736694,0.023132324,0.00057315826,0.024215698,-0.07244873,0.024993896,-0.016906738,0.0030841827,-0.012466431,0.039276123,0.028823853,0.026397705,-0.006450653,0.004